package cn.healthlife.local;
import org.junit.Test;
import static org.junit.Assert.*;

public final class GuestScopePolicy11614Test {
    private final String scope="guest:12345678-1234-4123-8123-123456789012";
    @Test public void guestHasNoFakePositiveMemberIdentity(){assertTrue(GuestScopePolicy11614.usable("guest",scope,"epoch-a",0,false));assertFalse(GuestScopePolicy11614.usable("member",scope,"epoch-a",0,false));assertFalse(GuestScopePolicy11614.usable("guest","member:88888888","epoch-a",88888888,false));}
    @Test public void pendingCleanupNeverGrantsMedia(){assertFalse(GuestScopePolicy11614.usable("guest",scope,"epoch-a",0,true));assertFalse(GuestScopePolicy11614.usable("member","member:29","epoch-a",29,true));}
    @Test public void lateCallbacksCannotCrossModeOrGuestEpoch(){assertTrue(GuestScopePolicy11614.same(scope,"one",scope,"one",false));assertFalse(GuestScopePolicy11614.same(scope,"one",scope,"two",false));assertFalse(GuestScopePolicy11614.same(scope,"one","member:29","one",false));assertFalse(GuestScopePolicy11614.same(scope,"one",scope,"one",true));assertFalse(GuestScopePolicy11614.same("","", "","",false));}
    @Test public void onlyAiNativeCapabilitiesAreAllowed(){for(String action:new String[]{"native.pickFile","native.pickImage","native.startVoice","native.copyText","native.openLink"})assertTrue(GuestScopePolicy11614.allowedNative(action));for(String action:new String[]{"native.update.download","native.reminders.refresh","account.erase","native.eval",null})assertFalse(GuestScopePolicy11614.allowedNative(action));}
    @Test public void guestCanUseOnlyTheFiveExactUpdaterActions(){for(String action:new String[]{"native.update.check","native.update.start","native.update.status","native.update.cancel","native.update.install"})assertTrue(action,GuestScopePolicy11614.allowedNative(action));for(String action:new String[]{"native.update","native.update.","native.update.download","native.update.delete","native.update.install.extra","native.update.check ","native.update.CHECK","native.updates.check","account.erase",null})assertFalse(action,GuestScopePolicy11614.allowedNative(action));}
    @Test public void updaterAllowanceDoesNotChangeMemberScopeGuards(){assertTrue(GuestScopePolicy11614.usable("member","member:29","epoch-a",29,false));assertFalse(GuestScopePolicy11614.usable("member","member:29","epoch-a",0,false));assertFalse(GuestScopePolicy11614.usable("member","member:30","epoch-a",29,false));assertFalse(GuestScopePolicy11614.usable("member","member:29","",29,false));assertFalse(GuestScopePolicy11614.usable("member","member:29","epoch-a",29,true));}
    @Test public void publicLoginToolReceiptDoesNotEndAnswer(){ChatStreamPolicy policy=new ChatStreamPolicy();assertTrue(policy.accept("start",1,5,7,0,200,false));assertTrue(policy.accept("login_required",2,5,7,0,200,false));assertTrue(policy.accept("answer_delta",3,5,7,3,200,false));assertTrue(policy.accept("done",4,5,7,0,200,false));assertFalse(policy.accept("answer_delta",5,5,7,1,200,false));}
    @Test public void loginReceiptCannotBypassStreamIdentityOrPrivateReasoningGuard(){ChatStreamPolicy policy=new ChatStreamPolicy();assertFalse(policy.accept("login_required",1,5,7,0,200,false));assertTrue(policy.accept("start",1,5,7,0,200,false));assertFalse(policy.accept("login_required",2,6,7,0,200,false));assertFalse(policy.accept("login_required",2,5,7,0,200,true));}
}
